def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    vowel_map = {}

    # Create mapping for vowels: replace with letter 2 positions ahead
    for vowel in 'aeiou':
        vowel_map[vowel] = chr(ord(vowel) + 2)
    for vowel in 'AEIOU':
        vowel_map[vowel] = chr(ord(vowel) + 2)

    result = []

    for char in message:
        if char in vowels:
            # Replace vowel with letter 2 positions ahead
            new_char = vowel_map[char]
        else:
            # Swap case
            if char.islower():
                new_char = char.upper()
            else:
                new_char = char.lower()

        result.append(new_char)

    return ''.join(result)

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = set('aeiouAEIOU')
    vowel_mapping = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = []
    for char in message:
        if char in vowels:
            result.append(vowel_mapping[char])
        else:
            # Swap case
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())

    return ''.join(result)

