    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    # Convert inputs to comparable numeric values
    def to_numeric(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal point
            val = val.replace(',', '.')
            return float(val)
        else:
            raise ValueError("Input must be int, float, or string")

    # Convert both values to numeric for comparison
    num_a = to_numeric(a)
    num_b = to_numeric(b)

    # Compare and return the larger value in original form
    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def file_name_check(file_name):
    # Check if there's exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into name and extension
    name, extension = file_name.split('.')

    # Check if the name part is not empty
    if not name:
        return 'No'

    # Check if the name starts with a latin alphabet letter
    if not name[0].isalpha():
        return 'No'

    # Check if there are no more than three digits in the entire file name
    digit_count = sum(1 for c in file_name if c.isdigit())
    if digit_count > 3:
        return 'No'

    # Check if the extension is one of the allowed types
    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

